viewof searchControl = {
  const container = html`
    &lt;div class="search-bar-container" style="max-width: 440px; margin: 0 auto 0.75rem auto;"&gt;
      &lt;div style="display: flex; gap: 8px; align-items: center;"&gt;
        &lt;input type="text" placeholder="your last.fm username here..." class="form-control" style="flex: 1; height: 38px; border-radius: 6px;" /&gt;
        &lt;button type="button" class="btn btn-primary search-btn" style="height: 38px; padding: 0 16px; border-radius: 6px; font-weight: 500;"&gt;search&lt;/button&gt;
        &lt;button type="button" class="btn btn-outline-secondary refresh-btn" title="Refresh" style="height: 38px; width: 38px; min-width: 38px; padding: 0; display: inline-flex; align-items: center; justify-content: center; border-radius: 6px;"&gt;
          &lt;svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" viewBox="0 0 16 16"&gt;
            &lt;path fill-rule="evenodd" d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2z"/&gt;
            &lt;path d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466"/&gt;
          &lt;/svg&gt;
        &lt;/button&gt;
      &lt;/div&gt;
    &lt;/div&gt;
  `;

  const input = container.querySelector('input');
  const searchBtn = container.querySelector('.search-btn');
  const refreshBtn = container.querySelector('.refresh-btn');

  input.addEventListener('input', (e) =&gt; e.stopPropagation());
  input.addEventListener('change', (e) =&gt; e.stopPropagation());
  input.addEventListener('keydown', (e) =&gt; {
    if (e.key === 'Enter') {
      e.preventDefault();
      triggerSearch();
    }
  });

  container.value = { username: "", trigger: 0 };

  function triggerSearch() {
    const val = input.value.trim();
    if (!val) return;
    container.value = { username: val, trigger: container.value.trigger + 1 };
    container.dispatchEvent(new CustomEvent("input"));
  }

  window.triggerChartFMSearch = (val) =&gt; {
    input.value = val;
    triggerSearch();
  };

  searchBtn.onclick = triggerSearch;
  refreshBtn.onclick = triggerSearch;

  return container;
}

