  const header = container.querySelector('.settings-tab-header');
  const panel = container.querySelector('.settings-tab-panel');
  const chevron = container.querySelector('.chevron');
  const slider = container.querySelector('input[type="range"]');
  const badge = container.querySelector('.count-display');
  const settingsInput = container.querySelector('.settings-input');
  const settingsSearchBtn = container.querySelector('.settings-search-btn');
  const settingsRefreshBtn = container.querySelector('.settings-refresh-btn');

  settingsInput.addEventListener('input', (e) =&gt; e.stopPropagation());
  settingsInput.addEventListener('change', (e) =&gt; e.stopPropagation());

  function doSettingsSearch() {
    const val = settingsInput.value.trim();
    if (!val) return;
    if (typeof window.triggerChartFMSearch === "function") {
      window.triggerChartFMSearch(val);
    } else {
      const mainInput = document.querySelector('.search-bar-container input');
      const mainBtn = document.querySelector('.search-bar-container .btn-primary');
      if (mainInput && mainBtn) {
        mainInput.value = val;
        mainBtn.click();
      }
    }
  }

  settingsInput.addEventListener('keydown', (e) =&gt; {
    if (e.key === 'Enter') {
      e.preventDefault();
      doSettingsSearch();
    }
